pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);

    pm.test("Token", function () {
        var jsonData = pm.response.json();
        var info = jsonData.data.basicInfo || {};

        var userType = info.accountState.userType;

        pm.collectionVariables.set("token", jsonData.data.token);
        pm.collectionVariables.set("refreshToken", jsonData.data.refreshToken);
        if (userType === "business") pm.collectionVariables.set("businessToken", jsonData.data.token);
        else if (userType === "admin") pm.collectionVariables.set("adminToken", jsonData.data.token);
        else pm.collectionVariables.set("userToken", jsonData.data.token);

        pm.collectionVariables.set("email", info.email);
        pm.collectionVariables.set("phoneNumber", info.phoneNumber);

        let requestBody = JSON.parse(pm.request.body.raw);
        pm.collectionVariables.set("password", requestBody.password);
    });
});

