// Parse the raw request body
let requestBody = pm.request.body.raw;

try {
    let jsonData = JSON.parse(requestBody); // Parse the raw request body to JSON
    let email = jsonData.email; // Access the email field

    // Now set the collectionVariables variable
    pm.collectionVariables.set("InvalidEmail", email);
    console.log("Email extracted and set to collectionVariables variable:", email);
} catch (e) {
    console.log("Error parsing request body:", e);
}

// Generate a random 7-digit number for the phone number
let randomPhoneNumber = Math.floor(1000000 + Math.random() * 9000000);

// Choose a valid mobile network code in Pakistan
let validMobileNetworkCode = Math.floor(300 + Math.random() * 8); // Random number between 300 and 307 (valid codes)

// Set the phone number with Pakistan country code
let internationalPhoneNumber = `+92${validMobileNetworkCode}${randomPhoneNumber}`;

// Store the generated phone number in an environment variable
pm.environment.set("randomPhoneNumber", internationalPhoneNumber);

console.log("Generated Phone Number:", internationalPhoneNumber);


// Generate a random number
let randomNumber = Math.floor(Math.random() * 10000); // Generates a number between 0 and 9999

// Create a random email using the random number
let randomEmail = `testuser${randomNumber}@gmail.com`;

// Store the generated email in an environment variable
pm.environment.set("randomEmail", randomEmail);

console.log("Generated Email:", randomEmail);

request.description:
### Register User

This endpoint is used to register a new user.

#### Request Body

- `profileIcon` (string): Unique identifier referencing a profile Bitmoji.

- `name` (string): The user's full name.

- `annonymousName` (string): A randomly generated username.

- `email` (string): The user's email address.

- `phoneNumber` (string): The user's phone number.

- `phoneNote` (string): Additional note about the phone number.

- `password` (string): The user's chosen password.

- `deviceType` (string): The type of device (android/ios).

- `deviceId` (string): The device ID from Firebase FCM.

- `timezone` (string): The user's timezone.


#### Response (JSON Schema)

``` json
{
    "type": "object",
    "properties": {
        "message": {
            "type": "string"
        },
        "data": {
            "type": "object",
            "properties": {
                "basicInfo": {
                    "type": "object",
                    "properties": {
                        "profileIcon": {
                            "type": "string"
                        },
                        "name": {
                            "type": "string"
                        },
                        "annonymousName": {
                            "type": "string"
                        },
                        "email": {
                            "type": "string"
                        },
                        "phoneNumber": {
                            "type": "string"
                        },
                        "phoneNote": {
                            "type": "string"
                        }
                    }
                },
                "accountState": {
                    "type": "object",
                    "properties": {
                        "userType": {
                            "type": "string"
                        },
                        "status": {
                            "type": "string"
                        },
                        "verificationStatus": {
                            "type": "string"
                        }
                    }
                },
                "profileCompletionStatus": {
                    "type": "object",
                    "properties": {
                        "personalDetails": {
                            "type": "boolean"
                        },
                        "pregnancyDetails": {
                            "type": "boolean"
                        },
                        "lossDetails": {
                            "type": "boolean"
                        },
                        "healingDetails": {
                            "type": "boolean"
                        }
                    }
                },
                "metadata": {
                    "type": "object",
                    "properties": {
                        "_id": {
                            "type": "string"
                        },
                        "timezone": {
                            "type": "string"
                        },
                        "createdAt": {
                            "type": "string"
                        },
                        "updatedAt": {
                            "type": "string"
                        },
                        "__v": {
                            "type": "integer"
                        }
                    }
                },
                "otpInfo": {
                    "type": "object",
                    "properties": {
                        "otp": {
                            "type": "string"
                        },
                        "otpUsed": {
                            "type": "boolean"
                        },
                        "otpExpires": {
                            "type": "string"
                        }
                    }
                }
            }
        }
    }
}

